def can(a, x, k):
    cnt = 0
    for v in a:
        cnt += v // x
    return cnt >= k

static boolean can(int[] a, int x, int k) {
    long cnt = 0;
    for (int v : a) cnt += v / x;
    return cnt >= k;
}

function can(a, x, k) {
  let cnt = 0;
  for (const v of a) cnt += Math.floor(v / x);
  return cnt >= k;
}

bool can(const vector<int>& a, int x, int k) {
    long long cnt = 0;
    for (int v : a) cnt += v / x;
    return cnt >= k;
